CREATE TABLE IF NOT EXISTS products (
  id INT,
  name VARCHAR(255),
  category VARCHAR(128),
  unit_price DOUBLE
);
CREATE TABLE IF NOT EXISTS sales_orders (
  id INT,
  customer_name VARCHAR(255),
  employee_id INT,
  product_id INT,
  quantity INT,
  order_date VARCHAR(32),
  amount DOUBLE
);


